(() => {
  const clean = (s) => (s || '').replace(/\u00a0/g, ' ').trim();
  const vis = (e) => { const r = e.getBoundingClientRect(); return r.width > 2 && r.height > 2; };
  const lbl = (e) => { const p = e.closest('div[class*=form-item]') || e.parentElement; return clean(p && p.innerText).slice(0, 30); };
  const blk = document.getElementById('history');
  if (!blk) return 'NO BLOCK';
  return {
    text: clean(blk.innerText).slice(0, 700),
    fields: [...blk.querySelectorAll('input,textarea,[contenteditable=true]')].map((e, i) => {
      return {i: i, vis: vis(e), tag: e.tagName, ro: !!e.readOnly, ph: (e.placeholder || '').slice(0, 26), val: clean(e.value || e.innerText).slice(0, 40), lbl: lbl(e)};
    }).slice(0, 26),
    kas: [...blk.querySelectorAll('[ka]')].map((e) => e.getAttribute('ka') + '|' + clean(e.innerText).slice(0, 12) + '|w=' + Math.round(e.getBoundingClientRect().width)).slice(0, 40)
  };
})()
